  for mechanic in select lesson.id,lesson.title from public.lessons lesson join public.chapters chapter on chapter.id=lesson.chapter_id join public.course_subject_offerings offering on offering.id=chapter.subject_offering_id join public.subjects subject on subject.id=offering.subject_id join public.levels level on level.id=offering.level_id join public.series series on series.id=offering.series_id where subject.name='Physique-Chimie' and level.name='Terminale' and series.name in ('C','D') and chapter.title='PHYSIQUE — MÉCANIQUE' and lesson.title in ('Mouvement du centre d''inertie d’un solide','Interaction gravitationnelle','Mouvements dans les champs (E et B)','Mouvements dans les champs (E et B) uniformes','Oscillations mécaniques libres') and not lesson.is_test_data loop if mechanic.title='Mouvement du centre d''inertie d’un solide' then marker:=':::force-diagram-solid'; elsif mechanic.title='Interaction gravitationnelle' then marker:=':::force-diagram-satellite'; elsif mechanic.title in ('Mouvements dans les champs (E et B)','Mouvements dans les champs (E et B) uniformes') then marker:=':::force-diagram-projectile'; else marker:=':::force-diagram-oscillator'; end if; update public.exercises set content_markdown=rtrim(coalesce(content_markdown,''))||E'\n\n'||marker where lesson_id=mechanic.id and not is_test_data and position(marker in coalesce(content_markdown,''))=0; if mechanic.title in ('Mouvements dans les champs (E et B)','Mouvements dans les champs (E et B) uniformes') and position(':::trajectory-simulator-uniform-fields' in coalesce((select content from public.lessons where id=mechanic.id),''))=0 then update public.lessons set content=rtrim(content)||E'\n\n:::trajectory-simulator-uniform-fields' where id=mechanic.id; end if; end loop;
end $pc_c_electromagnetism_published_do$;